def normalize(text: str) -> str:
    text = unicodedata.normalize("NFKC", text).casefold().replace("ё", "е")
    return re.sub(r"[\s‐‑–—-]+", " ", text).strip()


def next_letter(name: str) -> str:
    return next(c for c in reversed(normalize(name)) if c.isalpha() and c not in "ьъы")


@dataclass(frozen=True)
class City:
    id: str
    name: str
    english_name: str
    country: str
    population: int
    latitude: float
    longitude: float
    aliases: tuple[str, ...]


class Atlas:
    def __init__(self):
        self.cities = []
        self.by_name = {}
        countries = Locale("ru").territories
        for key, data in geonamescache.GeonamesCache().get_cities().items():
            russian = sorted({n for n in data["alternatenames"]
                              if re.fullmatch(r"[А-ЯЁа-яё][А-ЯЁа-яё \-]+", n)},
                             key=lambda n: (not n[0].isupper(), len(n), n))
            if not russian:
                continue
            city = City(str(key), russian[0], data["name"],
                        countries.get(data["countrycode"], data["countrycode"]),
                        data["population"], data["latitude"], data["longitude"],
                        tuple(dict.fromkeys(normalize(n) for n in russian)))
            self.cities.append(city)
            for alias in city.aliases:
                self.by_name.setdefault(alias, []).append(city)
        for matches in self.by_name.values():
            matches.sort(key=lambda city: city.population, reverse=True)
        self.preferred = {}
        for name in BOT_NAMES.replace("\n", "").split("|"):
            matches = self.by_name.get(normalize(name), [])
            if matches:
                self.preferred[matches[0].id] = name
        self.cities = [replace(c, name=self.preferred[c.id]) for c in self.cities
                       if c.id in self.preferred]

    def find(self, text: str):
        matches = self.by_name.get(normalize(text), [])
        if not matches:
            return None
        city = matches[0]
        return replace(city, name=self.preferred.get(city.id, text.strip()))

    def choose(self, letter: str, used: set[str]):
        candidates = [c for c in self.cities
                      if normalize(c.name).startswith(letter) and c.id not in used
                      and not used.intersection(c.aliases)]
        # Чаще отвечаем узнаваемыми городами, но не всегда одним и тем же.
        candidates.sort(key=lambda city: city.population, reverse=True)
        return random.choice(candidates[:20]) if candidates else None


@dataclass
class Game:
    used: set[str] = field(default_factory=set)
    expected: str = ""
    turns: int = 0

    def move(self, text: str, atlas: Atlas):
        city = atlas.find(text)
        if not city:
            raise ValueError("Не нашёл такой город в справочнике. Напиши название по-русски, без слова «город».")
        if city.id in self.used or self.used.intersection(city.aliases):
            raise ValueError("Этот город уже был! Попробуй другой.")
        if self.expected and not normalize(text).startswith(self.expected):
            raise ValueError(f"Сейчас нужен город на букву «{self.expected.upper()}».")
        self.used.update((city.id, *city.aliases))
        self.turns += 1
        reply = atlas.choose(next_letter(text), self.used)
        if reply:
            self.used.update((reply.id, *reply.aliases))
            self.expected = next_letter(reply.name)
        return city, reply

"""Получение статьи и фотографии с проверкой координат города."""
import math
from urllib.parse import quote

import httpx



def near_city(page: dict, city: City) -> bool:
    for coord in page.get("coordinates", []):
        lat1, lat2 = map(math.radians, (city.latitude, coord["lat"]))
        dlat = lat2 - lat1
        dlon = math.radians(coord["lon"] - city.longitude)
        a = math.sin(dlat / 2) ** 2 + math.cos(lat1) * math.cos(lat2) * math.sin(dlon / 2) ** 2
        if 12742 * math.asin(min(1, math.sqrt(a))) < 30:
            return True
    return False


class Wikipedia:
    def __init__(self):
        self.client = httpx.AsyncClient(timeout=12, headers={
            "User-Agent": "CitiesGameBot/1.0 (educational Telegram city game)"})
        self.cache = {}

    async def close(self):
        await self.client.aclose()

    async def get(self, city: City) -> tuple[str, str | None]:
        if city.id in self.cache:
            return self.cache[city.id]
        for lang, title in (("ru", city.name), ("en", city.english_name)):
            try:
                response = await self.client.get(f"https://{lang}.wikipedia.org/w/api.php", params={
                    "action": "query", "format": "json", "formatversion": 2,
                    "titles": f"{title}|{title} (город)", "redirects": 1,
                    "prop": "pageimages|info|coordinates", "inprop": "url",
                    "piprop": "thumbnail", "pithumbsize": 1000,
                })
                response.raise_for_status()
                for page in response.json().get("query", {}).get("pages", []):
                    if "missing" not in page and near_city(page, city):
                        result = (page["fullurl"], page.get("thumbnail", {}).get("source"))
                        self.cache[city.id] = result
                        return result
            except (httpx.HTTPError, ValueError, KeyError):
                continue
        # Поисковая ссылка честнее ссылки на непроверенную одноимённую статью.
        return ("https://ru.wikipedia.org/w/index.php?search=" + quote(f"{city.name} {city.country}"), None)

"""Запуск: python bot.py. Токен хранится в .env рядом с этим файлом."""
import html
import logging
import os
from pathlib import Path

from dotenv import load_dotenv
from telegram import BotCommand, InlineKeyboardButton, InlineKeyboardMarkup, Update, WebAppInfo, MenuButtonWebApp
from telegram.error import TelegramError
from telegram.ext import Application, CommandHandler, ContextTypes, MessageHandler, filters


RULES = (
    "🌍 Играем в города!\n\n"
    "Ты называешь город — я отвечаю городом на его последнюю букву. "
    "Затем твой ход на последнюю букву моего города. Ь, Ъ и Ы пропускаем, Ё = Е. "
    "Повторять города нельзя.\n\n"
    "Пришлю страну, население, фото и Википедию для обоих городов. "
    "Названия пиши по-русски. При совпадении названий выбираю самый населённый город.\n\n"
    "/new — новая игра\n/help — правила\n\nНачинай с любого города!"
)


async def setup(app: Application):
    app.bot_data["atlas"] = Atlas()
    app.bot_data["wiki"] = Wikipedia()
    await app.bot.set_my_commands([
        BotCommand("start", "Начать игру"), BotCommand("new", "Новая игра"),
        BotCommand("help", "Правила игры"), BotCommand("app", "Открыть Mini App"),
    ])
    url = os.getenv("MINI_APP_URL", "").strip()
    if url:
        if not url.startswith("https://"):
            raise ValueError("MINI_APP_URL должен начинаться с https://")
        await app.bot.set_chat_menu_button(menu_button=MenuButtonWebApp(text="Играть", web_app=WebAppInfo(url=url)))


async def shutdown(app: Application):
    await app.bot_data["wiki"].close()


async def start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    context.chat_data["game"] = Game()
    await update.effective_message.reply_text(RULES)
    if os.getenv("MINI_APP_URL") and update.effective_chat.type == "private":
        await open_app(update, context)


async def open_app(update: Update, context: ContextTypes.DEFAULT_TYPE):
    url = os.getenv("MINI_APP_URL", "").strip()
    if not url:
        await update.effective_message.reply_text("Mini App ещё не подключено. Укажи MINI_APP_URL в .env и перезапусти бота.")
    elif update.effective_chat.type != "private":
        await update.effective_message.reply_text("Открой личный чат со мной и отправь /app, чтобы запустить Mini App.")
    else:
        await update.effective_message.reply_text("🌍 Открой свой атлас путешествий: игра, фото городов, карта и личные рекорды.", reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("Открыть игру", web_app=WebAppInfo(url=url))]]))


async def help_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await update.effective_message.reply_text(RULES)


async def card(message, city, heading: str, wiki: Wikipedia):
    url, photo = await wiki.get(city)
    population = f"{city.population:,}".replace(",", " ") if city.population else "нет данных"
    caption = (f"{heading}: <b>{html.escape(city.name)}</b>\n"
               f"Страна: {html.escape(city.country)}\n"
               f"Население: {population}\n"
               "Данные: GeoNames (справочная оценка).")
    keyboard = InlineKeyboardMarkup([[InlineKeyboardButton("📖 Википедия", url=url)]])
    if photo:
        try:
            await message.reply_photo(photo, caption=caption, parse_mode="HTML", reply_markup=keyboard)
            return
        except TelegramError:
            pass
    await message.reply_text(caption + "\nФото сейчас недоступно.", parse_mode="HTML", reply_markup=keyboard)


async def play(update: Update, context: ContextTypes.DEFAULT_TYPE):
    message = update.effective_message
    game = context.chat_data.setdefault("game", Game())
    if len(message.text) > 100:
        await message.reply_text("Напиши только название города, до 100 символов.")
        return
    try:
        player_city, bot_city = game.move(message.text, context.bot_data["atlas"])
    except ValueError as error:
        await message.reply_text(str(error))
        return
    await card(message, player_city, "📍 Твой город", context.bot_data["wiki"])
    if bot_city:
        await card(message, bot_city, "🤖 Мой город", context.bot_data["wiki"])
        await message.reply_text(f"Тебе на «{game.expected.upper()}»! Ходов: {game.turns}.")
    else:
        await message.reply_text("Ты победил! У меня закончились подходящие города. /new — сыграть ещё.")
        context.chat_data.pop("game", None)


async def error_handler(update: object, context: ContextTypes.DEFAULT_TYPE):
    # Не записываем URL запросов Telegram: они содержат токен.
    logging.getLogger(__name__).warning("Ошибка обработки: %s", type(context.error).__name__)
    if isinstance(update, Update) and update.effective_message:
        try:
            game = context.chat_data.get("game")
            hint = f" Текущая буква: «{game.expected.upper()}»." if game and game.expected else ""
            await update.effective_message.reply_text("Не удалось отправить ответ." + hint + " /new — новая игра.")
        except TelegramError:
            pass


def main():
    load_dotenv(Path(__file__).with_name(".env"))
    token = os.getenv("TELEGRAM_BOT_TOKEN", "").strip()
    if not token or token == "put_your_botfather_token_here":
        raise SystemExit("Укажи TELEGRAM_BOT_TOKEN в файле .env. Инструкция — в README.md.")
    logging.basicConfig(level=logging.WARNING)
    app = (Application.builder().token(token).concurrent_updates(False)
           .post_init(setup).post_shutdown(shutdown).build())
    app.add_handler(CommandHandler(["start", "new"], start))
    app.add_handler(CommandHandler("help", help_command))
    app.add_handler(CommandHandler("app", open_app))
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, play))
    app.add_error_handler(error_handler)
    print("Бот запущен. Для остановки нажми Ctrl+C.")
    app.run_polling(allowed_updates=["message"])



